// Helper function to convert Zod schema to mcp-use inputs format
function zodToInputs(schema: z.ZodObject<any>) {
  const shape = schema.shape;
  return Object.entries(shape).map(([key, value]: [string, any]) => ({
    name: key,
    type: value._def.typeName === "ZodString" ? "string"
      : value._def.typeName === "ZodNumber" ? "number"
        : value._def.typeName === "ZodBoolean" ? "boolean"
          : "string",
    required: !value.isOptional(),
  }));
}

